WITH with_prev AS (SELECT *, LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) AS prev_event_time FROM web_events), flagged AS (SELECT *, CASE WHEN prev_event_time IS NULL OR event_time > prev_event_time + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS new_group_flag FROM with_prev), sessionized AS (SELECT *, SUM(new_group_flag) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT CASE WHEN session_no >= 6 THEN 'LARGE' ELSE 'SMALL' END AS session_no_tier, DATE_TRUNC('QUARTER', event_time) AS quarter_start, page, COUNT(DISTINCT id) AS distinct_ids, COUNT(DISTINCT id) AS distinct_ids_2 FROM sessionized GROUP BY GROUPING SETS ((CASE WHEN session_no >= 6 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('QUARTER', event_time), page), (CASE WHEN session_no >= 6 THEN 'LARGE' ELSE 'SMALL' END, DATE_TRUNC('QUARTER', event_time))) ORDER BY distinct_ids_2 DESC;
